-- Vice City Central Phase 3.5: private activity notifications.
-- Run in Supabase Dashboard > SQL Editor > New query.
-- Notifications are generated by database triggers; browser clients cannot insert them directly.

create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  recipient_id uuid not null references public.profiles (id) on delete cascade,
  actor_id uuid references public.profiles (id) on delete set null,
  type text not null check (type in ('follow', 'post_like', 'comment', 'reply', 'poll_vote')),
  post_id uuid references public.posts (id) on delete cascade,
  comment_id uuid references public.comments (id) on delete cascade,
  poll_id uuid references public.polls (id) on delete cascade,
  created_at timestamptz not null default now(),
  read_at timestamptz,
  constraint notifications_no_self_activity check (actor_id is null or actor_id <> recipient_id),
  constraint notifications_target_matches_type check (
    (type = 'follow' and post_id is null and comment_id is null and poll_id is null)
    or (type = 'post_like' and post_id is not null and comment_id is null and poll_id is null)
    or (type in ('comment', 'reply') and post_id is not null and comment_id is not null and poll_id is null)
    or (type = 'poll_vote' and post_id is null and comment_id is null and poll_id is not null)
  )
);

create index if not exists notifications_recipient_created_idx
  on public.notifications (recipient_id, created_at desc);
create index if not exists notifications_unread_idx
  on public.notifications (recipient_id, created_at desc)
  where read_at is null;

alter table public.notifications enable row level security;
alter table public.notifications replica identity full;

drop policy if exists "Members can view their own notifications" on public.notifications;
create policy "Members can view their own notifications"
on public.notifications for select
to authenticated
using (auth.uid() = recipient_id);

drop policy if exists "Members can mark their own notifications as read" on public.notifications;
create policy "Members can mark their own notifications as read"
on public.notifications for update
to authenticated
using (auth.uid() = recipient_id)
with check (auth.uid() = recipient_id);

revoke all on public.notifications from anon, authenticated;
grant select on public.notifications to authenticated;
grant update (read_at) on public.notifications to authenticated;

-- A new follower notifies the member being followed.
create or replace function public.notify_member_follow()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.follower_id <> new.following_id then
    insert into public.notifications (recipient_id, actor_id, type)
    values (new.following_id, new.follower_id, 'follow');
  end if;
  return new;
end;
$$;

drop trigger if exists notifications_after_member_follow on public.member_follows;
create trigger notifications_after_member_follow
after insert on public.member_follows
for each row execute function public.notify_member_follow();

-- A new like notifies the author of the liked discussion.
create or replace function public.notify_post_like()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.notifications (recipient_id, actor_id, type, post_id)
  select p.author_id, new.user_id, 'post_like', new.post_id
  from public.posts p
  where p.id = new.post_id
    and p.status = 'published'
    and p.author_id <> new.user_id;
  return new;
end;
$$;

drop trigger if exists notifications_after_post_like on public.post_likes;
create trigger notifications_after_post_like
after insert on public.post_likes
for each row execute function public.notify_post_like();

-- A top-level comment notifies the post author; a reply notifies its parent-comment author.
create or replace function public.notify_comment_activity()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_user_id uuid;
begin
  if new.parent_comment_id is not null then
    select c.author_id
      into target_user_id
    from public.comments c
    where c.id = new.parent_comment_id
      and c.status = 'published';

    if target_user_id is not null and target_user_id <> new.author_id then
      insert into public.notifications (recipient_id, actor_id, type, post_id, comment_id)
      values (target_user_id, new.author_id, 'reply', new.post_id, new.id);
    end if;
  else
    select p.author_id
      into target_user_id
    from public.posts p
    where p.id = new.post_id
      and p.status = 'published';

    if target_user_id is not null and target_user_id <> new.author_id then
      insert into public.notifications (recipient_id, actor_id, type, post_id, comment_id)
      values (target_user_id, new.author_id, 'comment', new.post_id, new.id);
    end if;
  end if;

  return new;
end;
$$;

drop trigger if exists notifications_after_comment on public.comments;
create trigger notifications_after_comment
after insert on public.comments
for each row execute function public.notify_comment_activity();

-- A vote notifies the poll creator, without exposing which option the voter selected.
create or replace function public.notify_poll_vote()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  poll_owner_id uuid;
begin
  select p.created_by
    into poll_owner_id
  from public.polls p
  where p.id = new.poll_id;

  if poll_owner_id is not null and poll_owner_id <> new.user_id then
    insert into public.notifications (recipient_id, actor_id, type, poll_id)
    values (poll_owner_id, new.user_id, 'poll_vote', new.poll_id);
  end if;

  return new;
end;
$$;

drop trigger if exists notifications_after_poll_vote on public.poll_votes;
create trigger notifications_after_poll_vote
after insert on public.poll_votes
for each row execute function public.notify_poll_vote();

-- Trigger functions are not callable as ordinary client RPCs.
revoke all on function public.notify_member_follow() from public, anon, authenticated;
revoke all on function public.notify_post_like() from public, anon, authenticated;
revoke all on function public.notify_comment_activity() from public, anon, authenticated;
revoke all on function public.notify_poll_vote() from public, anon, authenticated;

-- Publish notifications to Realtime. RLS ensures each member receives only their own rows.
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (
       select 1 from pg_publication_tables
       where pubname = 'supabase_realtime'
         and schemaname = 'public'
         and tablename = 'notifications'
     ) then
    alter publication supabase_realtime add table public.notifications;
  end if;
end;
$$;
